// Reads rich lead data from message.artifact.structuredOutputs (new VAPI system)
// Handles BOTH inbound and outbound calls (detected via call.assistantOverrides.metadata.source)
const incoming = $input.first().json;
const body = incoming.body || incoming;
const msg = body.message || body;

if (msg.type !== 'end-of-call-report') { return []; }

const artifact = msg.artifact || {};
const soMap = artifact.structuredOutputs || {};

let intakeResult = null;
let callSummaryFromSO = null;
let sentimentFromSO = null;
let successPassFail = null;
let successNumeric = null;
let sergioExtras = null;
for (const key of Object.keys(soMap)) {
  const item = soMap[key] || {};
  const name = (item.name || '').toLowerCase();
  if (name === 'wcl loan intake details') intakeResult = item.result || null;
  else if (name === 'call summary') callSummaryFromSO = item.result || null;
  else if (name === 'customer sentiment') sentimentFromSO = item.result || null;
  else if (name === 'success evaluation - pass/fail') successPassFail = item.result;
  else if (name === 'success evaluation - numeric scale') successNumeric = item.result;
  else if (name === 'sergio outbound extras') sergioExtras = item.result || null;
}

const analysis = msg.analysis || {};
const legacyStructured = analysis.structuredData || {};
const structured = intakeResult || legacyStructured || {};

const caller = structured.caller || {};
const callOutcome = structured.call_outcome || {};
const dscr = structured.dscr || {};
const ff = structured.fix_and_flip || {};

// ---- Determine inbound vs outbound ----
const callObj = msg.call || {};
const overrides = callObj.assistantOverrides || {};
const metadata = overrides.metadata || {};
const isOutbound = metadata.source === 'outbound_dialer';

// ---- Split name into first/last ----
const fullName = caller.full_name || '';
const nameParts = fullName.trim().split(/\s+/);
const firstName = nameParts[0] || '';
const lastName = nameParts.slice(1).join(' ') || '';

// ---- Phone number ----
const callerPhone = caller.phone || (msg.customer && msg.customer.number) || metadata.phone || '';
const callerEmail = caller.email || '';

// ---- Loan info ----
const loanType = structured.loan_type || '';
const propertyType = structured.property_type || '';
const transactionType = structured.transaction_type || '';

// ---- Call metadata ----
const vapiCallId = callObj.id || msg.call?.id || '';
const endedReason = msg.endedReason || '';
const durationSec = msg.durationSeconds || callObj.durationSeconds || 0;
const recordingUrl = artifact.recordingUrl || msg.recordingUrl || '';
const transcriptText = artifact.transcript || msg.transcript || '';
const transcriptUrl = artifact.transcriptUrl || '';
const startedAt = callObj.startedAt || msg.startedAt || new Date().toISOString();

// ---- Determine final call_status based on endedReason ----
const NO_ANSWER_REASONS = ['customer-did-not-answer', 'no-answer', 'assistant-did-not-receive-customer-audio'];
const VOICEMAIL_REASONS = ['voicemail', 'customer-busy'];
const BUSY_REASONS = ['busy', 'customer-busy'];
const FAILURE_REASONS_PREFIX = ['pipeline-error', 'twilio-failed', 'vonage-failed', 'call.in-progress.error'];

let callStatus = 'Completed';
let lastAttemptResult = 'Connected';
if (NO_ANSWER_REASONS.includes(endedReason)) { callStatus = 'No Answer'; lastAttemptResult = 'No Answer'; }
else if (VOICEMAIL_REASONS.includes(endedReason)) { callStatus = 'Voicemail'; lastAttemptResult = 'Voicemail'; }
else if (BUSY_REASONS.includes(endedReason)) { callStatus = 'Busy'; lastAttemptResult = 'Busy'; }
else if (FAILURE_REASONS_PREFIX.some(p => endedReason.startsWith(p))) { callStatus = 'Failed'; lastAttemptResult = 'Failed'; }

// ---- Hot lead detection ----
const hasContact = (callerEmail || callerPhone) && firstName;
const isHot = hasContact && loanType && loanType !== 'Unknown' && loanType !== '';

// Apply Sergio-captured corrections if present
if (sergioExtras) {
  if (sergioExtras.confirmed_first_name && !firstName) {
    // keep firstName as-is but log
  }
  if (sergioExtras.confirmed_email && (!callerEmail || callerEmail === 'N/A')) {
    // override callerEmail if inbound didn't have one
  }
}
// ---- Build sheetRow (maps 1:1 to Google Sheet columns) ----
