  dscr_monthly_rent: dscr.monthly_rent_actual || dscr.monthly_rent_market || '',
  dscr_purchase_price: dscr.purchase_price_or_value || '',
  dscr_target_ltv: dscr.ltv_percentage || '',
  dscr_estimated_pitia: dscr.monthly_pitia || '',
  dscr_credit_score_range: dscr.credit_score_range || '',
  dscr_liquid_reserves: dscr.liquid_reserves || '',
  dscr_vesting: dscr.vesting || '',
  dscr_rent_covers_pitia: dscr.rent_covers_pitia || '',
  dscr_habitable: dscr.property_is_habitable === true ? 'Yes' : (dscr.property_is_habitable === false ? 'No' : ''),
  ff_purchase_price: ff.purchase_price || '',
  ff_renovation_budget: ff.renovation_budget || '',
  ff_arv: ff.after_repair_value || '',
  ff_current_phase: ff.current_phase || '',
  ff_close_date: ff.close_of_escrow_date || '',
  ff_project_duration_months: ff.project_duration || '',
  ff_completed_flips_3yr: ff.completed_flips_last_3_years || '',
  ff_liquidity_available: ff.liquidity_available || '',
  ff_credit_score: ff.credit_score || '',
  ff_renovation_level: ff.renovation_level || '',
  ff_permits_needed: ff.permits_needed || '',
