  <div style="background:#f0fdf4;padding:12px;border-left:3px solid #059669;font-size:14px;line-height:1.5;border-radius:4px;">
    ${escapeHtml(callOutcome.qualification_summary)}
  </div>` : ''}

  <h3 style="color:#1a365d;margin-top:24px;margin-bottom:8px;font-size:15px;">Call Metadata</h3>
  <table style="width:100%;border-collapse:collapse;font-size:13px;color:#4b5563;">
