    ${sentimentFromSO ? `<tr><td style="padding:4px 0;">Sentiment</td><td>${escapeHtml(String(sentimentFromSO))}</td></tr>` : ''}
    ${recordingUrl ? `<tr><td style="padding:4px 0;">Recording</td><td><a href="${recordingUrl}" style="color:#1a365d;">Listen â†’</a></td></tr>` : ''}
  </table>

  <h3 style="color:#1a365d;margin-top:24px;margin-bottom:8px;font-size:15px;">Transcript</h3>
  <div style="background:#f9fafb;padding:12px;font-size:12px;line-height:1.6;white-space:pre-wrap;font-family:ui-monospace,'SF Mono',Menlo,monospace;max-height:400px;overflow:auto;border-radius:4px;border:1px solid #e5e7eb;">${escapeHtml(transcriptText)}</div>

  <p style="margin-top:24px;font-size:11px;color:#9ca3af;text-align:center;">Generated by Vapi â€” WCL Lead Intake Handler on buildflows.cloud</p>
</div>
`;

return [{
